// List returns every product.
// Imports:
import (
	"encoding/json"
	"net/http"
	"sync"
	"testing"
)

func (s *Store) List() []Product {
	s.mu.RLock()
	defer s.mu.RUnlock()
	out := make([]Product, 0, len(s.products))
	for _, product := range s.products {
		out = append(out, product)
	}
	return out
}

