import (
	"encoding/json"
	"net/http"
	"sync"
	"testing"
)

func handleList(lister Lister) http.HandlerFunc {
	return func(writer http.ResponseWriter, request *http.Request) {
		writer.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(writer).Encode(lister.List())
	}
}

