import (
	"encoding/json"
	"net/http"
	"sync"
	"testing"
)

func TestStorePutThenList(t *testing.T) {
	store := NewStore()
	store.Put(Product{ID: "a", Name: "Anchor", Price: 3.5})
	if len(store.List()) != 1 {
		t.Fatal("expected one product")
	}
}

